import { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { TRPCClientError } from "@trpc/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { BarChart3, CakeSlice, CalendarDays, ChevronRight, CircleDollarSign, ClipboardList, Clock3, Filter, Heart, LogIn, Menu, Package, Plus, Search, ShieldAlert, ShoppingBag, Sparkles, Trash2, TrendingUp, Truck, Users, Warehouse, X } from "lucide-react";

const statusLabels = { received: "Pedido recebido", in_production: "Em produção", ready: "Pronto", out_for_delivery: "Saiu para entrega", delivered: "Entregue", cancelled: "Cancelado" } as const;
const paymentLabels = { pix: "PIX", card: "Cartão", cash: "Dinheiro" } as const;
type CartItem = { productId: number; productName: string; quantity: number; unitPrice: string; options?: string; notes?: string };

type ProductDraft = { name: string; description: string; price: string; imageUrl: string; categoryId: string };
const blankProduct: ProductDraft = { name: "", description: "", price: "", imageUrl: "", categoryId: "" };
type IngredientDraft = { name: string; unit: string; currentQuantity: string; minimumQuantity: string; costPerUnit: string };
const blankIngredient: IngredientDraft = { name: "", unit: "g", currentQuantity: "0", minimumQuantity: "0", costPerUnit: "0" };

function money(value: string | number) { return Number(value).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }
// Server errors arrive as generic tRPC failures; surface the real reason (a
// permission problem vs. a validation message) instead of one canned string.
function errorMessage(error: unknown, fallback: string) {
  if (error instanceof TRPCClientError) {
    if (error.data?.code === "FORBIDDEN") return "Você não tem permissão de administrador para essa ação.";
    if (error.message) return error.message;
  }
  return fallback;
}

export default function Home() {
  const { user, isAuthenticated } = useAuth();
  const isAdmin = isAuthenticated && user?.role === "admin";
  const [mode, setMode] = useState<"store" | "admin">("store");
  const [adminSection, setAdminSection] = useState<"overview" | "orders" | "catalog" | "stock" | "production" | "finance">("overview");
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [trackingId, setTrackingId] = useState<string | null>(null);
  const [trackingPhone, setTrackingPhone] = useState("");
  const [showTracking, setShowTracking] = useState(false);
  const [showTrackingForm, setShowTrackingForm] = useState(false);
  const [trackingForm, setTrackingForm] = useState({ code: "", phone: "" });
  const [showFavorites, setShowFavorites] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [authMode, setAuthMode] = useState<"login" | "register">("login");
  const [authForm, setAuthForm] = useState({ name: "", email: "", password: "" });
  const [authError, setAuthError] = useState<string | null>(null);
  const [authPending, setAuthPending] = useState(false);
  const [search, setSearch] = useState("");
  const [productDraft, setProductDraft] = useState<ProductDraft>(blankProduct);
  const [categoryName, setCategoryName] = useState("");
  const [favorites, setFavorites] = useState<number[]>(() => { try { return JSON.parse(localStorage.getItem("miette-favorites") ?? "[]"); } catch { return []; } });
  const [editingProductId, setEditingProductId] = useState<number | null>(null);
  const [ingredientDraft, setIngredientDraft] = useState<IngredientDraft>(blankIngredient);
  const [checkout, setCheckout] = useState({ customerName: "", customerPhone: "", customerEmail: "", fulfillment: "pickup" as "pickup" | "delivery", deliveryAddress: "", scheduledAt: "", paymentMethod: "pix" as "pix" | "card" | "cash", notes: "" });
  const catalog = trpc.catalog.products.useQuery();
  const categories = trpc.catalog.categories.useQuery();
  const createOrder = trpc.orders.create.useMutation({ onSuccess: (order) => { setCart([]); setShowCheckout(false); setShowCart(false); setTrackingId(order?.trackingCode ?? null); setTrackingPhone(checkout.customerPhone); setShowTracking(true); toast.success(`Pedido #${order?.id ?? ""} recebido!`); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível confirmar o pedido.")) });
  const trackingOrder = trpc.orders.get.useQuery({ trackingCode: trackingId ?? "", customerPhone: trackingPhone || "00000000" }, { enabled: Boolean(trackingId) && trackingPhone.length >= 8 && showTracking, refetchInterval: 15000 });
  const adminSummary = trpc.dashboard.summary.useQuery(undefined, { enabled: mode === "admin" && isAdmin });
  const adminOrders = trpc.orders.list.useQuery(undefined, { enabled: mode === "admin" && isAdmin });
  const ingredients = trpc.inventory.list.useQuery(undefined, { enabled: mode === "admin" && isAdmin });
  const lowStock = trpc.inventory.lowStock.useQuery(undefined, { enabled: mode === "admin" && isAdmin });
  const productionAgenda = trpc.production.agenda.useQuery(undefined, { enabled: mode === "admin" && isAdmin });
  const paymentSummary = trpc.payments.summary.useQuery(undefined, { enabled: mode === "admin" && isAdmin });
  const utils = trpc.useUtils();
  useEffect(() => { localStorage.setItem("miette-favorites", JSON.stringify(favorites)); }, [favorites]);
  function toggleFavorite(productId: number) { setFavorites((current) => current.includes(productId) ? current.filter((id) => id !== productId) : [...current, productId]); }
  const createProduct = trpc.catalog.createProduct.useMutation({ onSuccess: () => { utils.catalog.products.invalidate(); setProductDraft(blankProduct); toast.success("Produto cadastrado no catálogo."); }, onError: (error) => toast.error(errorMessage(error, "Preencha os dados do produto corretamente.")) });
  const updateProduct = trpc.catalog.updateProduct.useMutation({ onSuccess: () => { utils.catalog.products.invalidate(); setProductDraft(blankProduct); setEditingProductId(null); toast.success("Produto atualizado."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível atualizar o produto.")) });
  const deleteProduct = trpc.catalog.deleteProduct.useMutation({ onSuccess: () => { utils.catalog.products.invalidate(); toast.success("Produto removido do catálogo."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível remover o produto.")) });
  const createCategoryMutation = trpc.catalog.createCategory.useMutation({ onSuccess: () => { utils.catalog.categories.invalidate(); setCategoryName(""); toast.success("Categoria criada."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível criar a categoria.")) });
  const deleteCategoryMutation = trpc.catalog.deleteCategory.useMutation({ onSuccess: () => { utils.catalog.categories.invalidate(); utils.catalog.products.invalidate(); toast.success("Categoria removida."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível remover a categoria.")) });
  const createIngredient = trpc.inventory.create.useMutation({ onSuccess: () => { utils.inventory.list.invalidate(); utils.inventory.lowStock.invalidate(); setIngredientDraft(blankIngredient); toast.success("Ingrediente cadastrado no estoque."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível cadastrar o ingrediente.")) });
  const updateStatus = trpc.orders.updateStatus.useMutation({ onSuccess: () => { utils.orders.list.invalidate(); utils.dashboard.summary.invalidate(); toast.success("Status do pedido atualizado."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível atualizar o status do pedido.")) });
  const updatePayment = trpc.payments.updateStatus.useMutation({ onSuccess: () => { utils.orders.list.invalidate(); utils.orders.get.invalidate(); utils.payments.summary.invalidate(); toast.success("Pagamento atualizado."); }, onError: (error) => toast.error(errorMessage(error, "Não foi possível atualizar o pagamento.")) });
  const products = catalog.data ?? [];
  const filteredProducts = products.filter(({ product }) => `${product.name} ${product.description}`.toLowerCase().includes(search.toLowerCase()));
  const subtotal = useMemo(() => cart.reduce((total, item) => total + Number(item.unitPrice) * item.quantity, 0), [cart]);
  const total = subtotal + (checkout.fulfillment === "delivery" ? 8 : 0);

  function addToCart(item: typeof products[number]) { setCart((current) => { const found = current.find((entry) => entry.productId === item.product.id); if (found) return current.map((entry) => entry.productId === item.product.id ? { ...entry, quantity: entry.quantity + 1 } : entry); return [...current, { productId: item.product.id, productName: item.product.name, quantity: 1, unitPrice: String(item.product.price) }]; }); toast.success(`${item.product.name} adicionado ao carrinho.`); }
  function submitOrder(event: React.FormEvent) { event.preventDefault(); if (!checkout.customerName || !checkout.customerPhone || !checkout.scheduledAt || cart.length === 0) { toast.error("Informe seus dados, o horário e adicione pelo menos um produto."); return; } if (checkout.fulfillment === "delivery" && !checkout.deliveryAddress) { toast.error("Informe o endereço de entrega."); return; } createOrder.mutate({ ...checkout, scheduledAt: new Date(checkout.scheduledAt), deliveryFee: checkout.fulfillment === "delivery" ? "8" : "0", items: cart }); }
  function updateCart(productId: number, delta: number) { setCart((items) => items.flatMap((item) => item.productId === productId ? (item.quantity + delta <= 0 ? [] : [{ ...item, quantity: item.quantity + delta }]) : [item])); }
  function editProduct(product: { id: number; name: string; description: string; price: string | number; imageUrl: string | null; categoryId: number | null }) { setEditingProductId(product.id); setProductDraft({ name: product.name, description: product.description, price: String(product.price), imageUrl: product.imageUrl ?? "", categoryId: product.categoryId != null ? String(product.categoryId) : "" }); setAdminSection("catalog"); }
  function handleProductSubmit(event: React.FormEvent) { event.preventDefault(); if (!productDraft.name || !productDraft.description || !productDraft.price) return toast.error("Preencha nome, descrição e preço."); const input = { name: productDraft.name, description: productDraft.description, price: productDraft.price, imageUrl: productDraft.imageUrl || undefined, categoryId: productDraft.categoryId ? Number(productDraft.categoryId) : undefined }; if (editingProductId) updateProduct.mutate({ id: editingProductId, ...input }); else createProduct.mutate(input); }
  async function submitAuth(event: React.FormEvent) {
    event.preventDefault();
    setAuthError(null);
    if (!authForm.email.trim() || !authForm.password) { setAuthError("Informe e-mail e senha."); return; }
    if (authMode === "register" && authForm.name.trim().length < 2) { setAuthError("Informe seu nome."); return; }
    setAuthPending(true);
    try {
      const endpoint = authMode === "login" ? "/api/auth/login" : "/api/auth/register";
      const body = authMode === "login" ? { email: authForm.email.trim(), password: authForm.password } : { ...authForm, email: authForm.email.trim() };
      const res = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify(body) });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) { setAuthError(data.error || "Não foi possível continuar."); return; }
      setShowLogin(false); setAuthForm({ name: "", email: "", password: "" }); setAuthMode("login");
      await utils.auth.me.invalidate();
      toast.success(authMode === "login" ? "Bem-vinda de volta!" : "Conta criada com sucesso!");
    } finally { setAuthPending(false); }
  }
  function submitTracking(event: React.FormEvent) { event.preventDefault(); const code = trackingForm.code.trim(); const phone = trackingForm.phone.trim(); if (code.length < 6 || phone.length < 8) { toast.error("Informe o código de rastreamento e o telefone usado no pedido."); return; } setTrackingId(code); setTrackingPhone(phone); setShowTrackingForm(false); setTrackingForm({ code: "", phone: "" }); setShowTracking(true); }

  return <div className="min-h-screen bg-[#fffaf7] text-[#2e2527]">
    <header className="sticky top-0 z-30 border-b border-[#f0e3dd] bg-[#fffaf7]/95 backdrop-blur"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8"><button onClick={() => { setMode("store"); setAdminSection("overview"); }} className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#f3c5b5] text-[#713d35]"><CakeSlice size={22} /></span><span className="text-left"><strong className="block font-serif text-xl tracking-tight">Miette</strong><small className="block text-[10px] uppercase tracking-[0.25em] text-[#a68179]">Confeitaria artesanal</small></span></button><nav className="hidden items-center gap-8 text-sm font-semibold text-[#7f6662] md:flex"><button onClick={() => setMode("store")} className={mode === "store" ? "text-[#ae594c]" : "hover:text-[#ae594c]"}>Encomendas</button><button onClick={() => setShowTrackingForm(true)} className="hover:text-[#ae594c]">Acompanhar pedido</button><button onClick={() => { setMode("admin"); setAdminSection("overview"); }} className={mode === "admin" ? "text-[#ae594c]" : "hover:text-[#ae594c]"}>Gestão da confeitaria</button></nav><div className="flex items-center gap-2"><button type="button" aria-label="Abrir favoritos" onClick={() => setShowFavorites(true)} className="rounded-full p-2 text-[#987d77] hover:bg-[#faeee9]"><Heart size={19} fill={favorites.length > 0 ? "currentColor" : "none"} /></button>{mode === "store" && <button onClick={() => setShowCart(true)} className="relative rounded-full bg-[#633f39] p-3 text-white hover:bg-[#7a4f47]"><ShoppingBag size={18} />{cart.length > 0 && <span className="absolute -right-1 -top-1 grid h-5 w-5 place-items-center rounded-full bg-[#e68e78] text-[10px] font-bold">{cart.reduce((sum, item) => sum + item.quantity, 0)}</span>}</button>}{!isAuthenticated && <button onClick={() => setShowLogin(true)} className="hidden items-center gap-2 rounded-xl border border-[#e8d8d1] px-3 py-2 text-xs font-bold text-[#754b43] sm:flex"><LogIn size={15} /> Entrar</button>}</div></div></header>

    {showLogin && <div className="fixed inset-0 z-[80] grid place-items-center bg-[#3b2522]/30 p-5 backdrop-blur-sm"><div className="w-full max-w-sm rounded-3xl bg-[#fffaf7] p-7 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[#b9796b]">{authMode === "login" ? "Bem-vinda de volta" : "Criar conta"}</p><h2 className="mt-1 font-serif text-3xl text-[#4d2e2a]">{authMode === "login" ? "Entrar" : "Cadastrar"}</h2></div><button type="button" onClick={() => { setShowLogin(false); setAuthError(null); }} className="rounded-full p-2 hover:bg-[#f9e9e2]"><X size={19} /></button></div><form onSubmit={submitAuth} className="mt-6 space-y-4">{authMode === "register" && <div className="space-y-2"><Label>Nome</Label><Input value={authForm.name} onChange={(e) => setAuthForm({ ...authForm, name: e.target.value })} placeholder="Seu nome" /></div>}<div className="space-y-2"><Label>E-mail</Label><Input type="email" value={authForm.email} onChange={(e) => setAuthForm({ ...authForm, email: e.target.value })} placeholder="voce@email.com" /></div><div className="space-y-2"><Label>Senha</Label><Input type="password" value={authForm.password} onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })} placeholder="Mínimo de 6 caracteres" /></div>{authError && <p className="text-sm text-[#ae594c]">{authError}</p>}<Button disabled={authPending} className="w-full rounded-xl bg-[#633f39] text-white hover:bg-[#7a4f47]">{authPending ? "Enviando..." : authMode === "login" ? "Entrar" : "Criar conta"}</Button></form><button type="button" onClick={() => { setAuthMode(authMode === "login" ? "register" : "login"); setAuthError(null); }} className="mt-4 w-full text-center text-xs font-bold text-[#87574e] hover:underline">{authMode === "login" ? "Ainda não tem conta? Criar agora" : "Já tem conta? Entrar"}</button></div></div>}
    {showTrackingForm && <div className="fixed inset-0 z-[80] grid place-items-center bg-[#3b2522]/30 p-5 backdrop-blur-sm"><div className="w-full max-w-sm rounded-3xl bg-[#fffaf7] p-7 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[#b9796b]">Acompanhamento</p><h2 className="mt-1 font-serif text-3xl text-[#4d2e2a]">Rastrear pedido</h2></div><button type="button" onClick={() => setShowTrackingForm(false)} className="rounded-full p-2 hover:bg-[#f9e9e2]"><X size={19} /></button></div><form onSubmit={submitTracking} className="mt-6 space-y-4"><div className="space-y-2"><Label>Código do pedido</Label><Input value={trackingForm.code} onChange={(e) => setTrackingForm({ ...trackingForm, code: e.target.value })} placeholder="Ex.: AB12CD34" /></div><div className="space-y-2"><Label>Telefone usado no pedido</Label><Input value={trackingForm.phone} onChange={(e) => setTrackingForm({ ...trackingForm, phone: e.target.value })} placeholder="(00) 00000-0000" /></div><Button className="w-full rounded-xl bg-[#633f39] text-white hover:bg-[#7a4f47]">Consultar pedido</Button></form></div></div>}
    {showFavorites && <div className="fixed inset-0 z-50"><button type="button" aria-label="Fechar favoritos" onClick={() => setShowFavorites(false)} className="absolute inset-0 bg-[#3b2522]/30 backdrop-blur-sm" /><aside className="absolute right-0 top-0 h-full w-full max-w-md overflow-y-auto bg-[#fffaf7] p-6 shadow-2xl"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[#b9796b]">Sua seleção</p><h2 className="mt-1 font-serif text-3xl text-[#4d2e2a]">Favoritos</h2></div><button type="button" onClick={() => setShowFavorites(false)} className="rounded-full p-2 hover:bg-[#f9e9e2]"><X size={20} /></button></div>{favorites.length === 0 ? <div className="py-20 text-center text-sm text-[#987d77]">Você ainda não favoritou nenhum produto.</div> : <div className="mt-8 space-y-3">{products.filter(({ product }) => favorites.includes(product.id)).map(({ product }) => <div key={product.id} className="flex items-center gap-3 rounded-2xl border border-[#f0e3dd] bg-white p-3"><div className="grid h-16 w-16 shrink-0 place-items-center overflow-hidden rounded-xl bg-[#f9e9e2] text-[#ca806d]">{product.imageUrl ? <img src={product.imageUrl} alt={product.name} className="h-full w-full object-cover" /> : <CakeSlice size={25} />}</div><div className="min-w-0 flex-1"><p className="truncate font-serif text-lg text-[#4d2e2a]">{product.name}</p><p className="text-sm text-[#ae594c]">{money(product.price)}</p></div><button type="button" onClick={() => toggleFavorite(product.id)} aria-label="Remover dos favoritos" className="rounded-full p-2 text-[#ae594c] hover:bg-[#f9e9e2]"><Heart size={17} fill="currentColor" /></button></div>)}</div>}</aside></div>}
    {mode === "store" ? <main><section className="relative overflow-hidden bg-[#f9e9e2]"><div className="mx-auto grid max-w-7xl items-center gap-10 px-5 py-16 sm:py-24 lg:grid-cols-[1.1fr_.9fr] lg:px-8"><div className="relative z-10"><Badge className="mb-5 rounded-full bg-[#ead0c5] px-4 py-2 text-[#87574e] hover:bg-[#ead0c5]"><Sparkles size={14} /> Feito para celebrar</Badge><h1 className="max-w-2xl font-serif text-5xl leading-[1.04] tracking-[-0.04em] text-[#4d2e2a] sm:text-7xl">Pequenos momentos, <i className="font-normal text-[#b96758]">grandes sabores.</i></h1><p className="mt-6 max-w-lg text-base leading-7 text-[#806761]">Doces artesanais preparados com ingredientes escolhidos e um toque de carinho em cada detalhe. Encomende para o seu próximo momento especial.</p><button onClick={() => document.getElementById("catalogo")?.scrollIntoView({ behavior: "smooth" })} className="mt-8 inline-flex items-center gap-2 rounded-xl bg-[#633f39] px-5 py-3.5 text-sm font-bold text-white shadow-lg shadow-[#633f39]/15 hover:bg-[#7a4f47]">Ver catálogo <ChevronRight size={17} /></button></div></div></section>
      <section id="catalogo" className="mx-auto max-w-7xl px-5 py-14 lg:px-8"><div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.24em] text-[#b9796b]">Nosso catálogo</p><h2 className="mt-2 font-serif text-4xl tracking-tight text-[#4d2e2a]">Escolha seu favorito</h2></div><div className="flex items-center gap-2 rounded-xl border border-[#eaded8] bg-white px-3 py-2"><Search size={17} className="text-[#aa8c85]" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar doces..." className="w-40 bg-transparent text-sm outline-none placeholder:text-[#b9a39d]" /></div></div><div className="mb-8 flex gap-2 overflow-x-auto pb-1"><button className="rounded-full bg-[#633f39] px-4 py-2 text-xs font-bold text-white">Todos</button>{(categories.data ?? []).map((category) => <button key={category.id} className="whitespace-nowrap rounded-full border border-[#eaded8] px-4 py-2 text-xs font-bold text-[#876b64] hover:bg-[#faeee9]">{category.name}</button>)}</div>{catalog.isLoading ? <div className="rounded-3xl bg-white p-16 text-center text-[#987d77]">Abrindo o catálogo...</div> : filteredProducts.length === 0 ? <div className="rounded-3xl border border-dashed border-[#e7d4cc] bg-white p-16 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#f9e9e2] text-[#b96758]"><CakeSlice size={25} /></div><h3 className="mt-4 font-serif text-2xl text-[#4d2e2a]">O cardápio está sendo preparado</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#987d77]">A confeitaria ainda não publicou produtos. Entre no painel de gestão para cadastrar o primeiro item do catálogo.</p><button onClick={() => setMode("admin")} className="mt-5 rounded-xl bg-[#633f39] px-4 py-3 text-xs font-bold text-white">Abrir gestão</button></div> : <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">{filteredProducts.map(({ product, category }) => <article key={product.id} className="group overflow-hidden rounded-3xl border border-[#f0e3dd] bg-white shadow-sm transition hover:-translate-y-1 hover:shadow-xl hover:shadow-[#d7b8aa]/20"><div className="relative grid aspect-[1.15] place-items-center overflow-hidden bg-[#f9e9e2] text-[#ca806d]">{product.imageUrl ? <img src={product.imageUrl} alt={product.name} className="h-full w-full object-cover" /> : <CakeSlice size={65} strokeWidth={1.2} />}<button type="button" aria-label={favorites.includes(product.id) ? "Remover dos favoritos" : "Adicionar aos favoritos"} onClick={() => toggleFavorite(product.id)} className={`absolute right-4 top-4 z-10 grid h-9 w-9 place-items-center rounded-full bg-white/90 shadow-sm transition hover:scale-105 ${favorites.includes(product.id) ? "text-[#ae594c]" : "text-[#987d77]"}`}><Heart size={17} fill={favorites.includes(product.id) ? "currentColor" : "none"} /></button><span className="absolute left-4 top-4 rounded-full bg-white/80 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-[#a76a5e]">{category?.name ?? "Artesanal"}</span></div><div className="p-5"><div className="flex items-start justify-between gap-3"><h3 className="font-serif text-2xl text-[#4d2e2a]">{product.name}</h3><strong className="whitespace-nowrap text-sm text-[#ae594c]">{money(product.price)}</strong></div><p className="mt-2 line-clamp-2 text-sm leading-6 text-[#987d77]">{product.description}</p><button onClick={() => addToCart({ product, category })} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl border border-[#dcbab0] py-3 text-xs font-bold text-[#87574e] transition hover:bg-[#633f39] hover:text-white"><Plus size={15} /> Adicionar ao pedido</button></div></article>)}</div>}</section></main> : <AdminView section={adminSection} setSection={setAdminSection} summary={adminSummary.data} paymentSummary={paymentSummary.data} productionAgenda={productionAgenda.data ?? []} orders={adminOrders.data ?? []} ingredients={ingredients.data ?? []} lowStock={lowStock.data ?? []} products={products} categories={categories.data ?? []} isAuthenticated={isAuthenticated} isAdmin={isAdmin} onRequestLogin={() => setShowLogin(true)} userName={user?.name ?? ""} productDraft={productDraft} setProductDraft={setProductDraft} editingProductId={editingProductId} productEdit={editProduct} productDelete={(id) => { if (window.confirm("Remover este produto do catálogo?")) deleteProduct.mutate({ id }); }} onCreateProduct={handleProductSubmit} categoryName={categoryName} setCategoryName={setCategoryName} onCreateCategory={(e) => { e.preventDefault(); if (!categoryName.trim()) { toast.error("Informe o nome da categoria."); return; } createCategoryMutation.mutate({ name: categoryName }); }} onDeleteCategory={(id) => { if (window.confirm("Remover esta categoria? Os produtos ficarão sem categoria.")) deleteCategoryMutation.mutate({ id }); }} ingredientDraft={ingredientDraft} setIngredientDraft={setIngredientDraft} onCreateIngredient={(e) => { e.preventDefault(); createIngredient.mutate(ingredientDraft); }} onUpdateStatus={(id, status) => updateStatus.mutate({ id, status })} onUpdatePayment={(orderId, status) => updatePayment.mutate({ orderId, status })} />}

    {showCart && <div className="fixed inset-0 z-50"><button onClick={() => setShowCart(false)} className="absolute inset-0 bg-[#3b2522]/30 backdrop-blur-sm" /><aside className="absolute right-0 top-0 h-full w-full max-w-md overflow-y-auto bg-[#fffaf7] p-6 shadow-2xl"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[#b9796b]">Seu pedido</p><h2 className="mt-1 font-serif text-3xl text-[#4d2e2a]">Carrinho</h2></div><button onClick={() => setShowCart(false)} className="rounded-full p-2 hover:bg-[#f9e9e2]"><X size={20} /></button></div>{cart.length === 0 ? <div className="py-20 text-center text-sm text-[#987d77]">Seu carrinho está vazio.</div> : <><div className="mt-8 space-y-4">{cart.map((item) => <div key={item.productId} className="flex items-center justify-between gap-4 rounded-2xl border border-[#f0e3dd] bg-white p-4"><div><p className="font-serif text-lg text-[#4d2e2a]">{item.productName}</p><p className="mt-1 text-sm text-[#ae594c]">{money(item.unitPrice)}</p></div><div className="flex items-center gap-2"><button onClick={() => updateCart(item.productId, -1)} className="grid h-7 w-7 place-items-center rounded-full bg-[#f9e9e2]">−</button><span className="w-4 text-center text-sm">{item.quantity}</span><button onClick={() => updateCart(item.productId, 1)} className="grid h-7 w-7 place-items-center rounded-full bg-[#f9e9e2]">+</button></div></div>)}</div><div className="mt-8 border-t border-[#eaded8] pt-5"><div className="flex justify-between text-sm text-[#987d77]"><span>Subtotal</span><strong className="text-[#4d2e2a]">{money(subtotal)}</strong></div><button onClick={() => setShowCheckout(true)} className="mt-5 w-full rounded-xl bg-[#633f39] py-4 text-sm font-bold text-white hover:bg-[#7a4f47]">Continuar para checkout <ChevronRight className="ml-2 inline" size={16} /></button></div></>}</aside></div>}
    {showCheckout && <div className="fixed inset-0 z-[60] overflow-y-auto bg-[#fffaf7] p-5 sm:p-10"><div className="mx-auto max-w-3xl"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[#b9796b]">Último passo</p><h2 className="mt-1 font-serif text-4xl text-[#4d2e2a]">Finalizar encomenda</h2></div><button onClick={() => setShowCheckout(false)} className="rounded-full p-2 hover:bg-[#f9e9e2]"><X /></button></div><form onSubmit={submitOrder} className="mt-8 grid gap-7 lg:grid-cols-[1fr_280px]"><div className="space-y-5 rounded-3xl border border-[#f0e3dd] bg-white p-6"><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Nome completo *</Label><Input value={checkout.customerName} onChange={(e) => setCheckout({ ...checkout, customerName: e.target.value })} placeholder="Como podemos chamar você?" /></div><div className="space-y-2"><Label>WhatsApp *</Label><Input value={checkout.customerPhone} onChange={(e) => setCheckout({ ...checkout, customerPhone: e.target.value })} placeholder="(00) 00000-0000" /></div></div><div className="space-y-2"><Label>E-mail</Label><Input type="email" value={checkout.customerEmail} onChange={(e) => setCheckout({ ...checkout, customerEmail: e.target.value })} placeholder="voce@email.com" /></div><div className="grid gap-3 sm:grid-cols-2"><button type="button" onClick={() => setCheckout({ ...checkout, fulfillment: "pickup" })} className={`rounded-xl border p-4 text-left ${checkout.fulfillment === "pickup" ? "border-[#b96758] bg-[#f9e9e2]" : "border-[#eaded8]"}`}><strong className="block text-sm">Retirada na loja</strong><span className="mt-1 block text-xs text-[#987d77]">Sem taxa de entrega</span></button><button type="button" onClick={() => setCheckout({ ...checkout, fulfillment: "delivery" })} className={`rounded-xl border p-4 text-left ${checkout.fulfillment === "delivery" ? "border-[#b96758] bg-[#f9e9e2]" : "border-[#eaded8]"}`}><strong className="block text-sm">Receber em casa</strong><span className="mt-1 block text-xs text-[#987d77]">Taxa fixa de {money(8)}</span></button></div>{checkout.fulfillment === "delivery" && <div className="space-y-2"><Label>Endereço de entrega *</Label><Input value={checkout.deliveryAddress} onChange={(e) => setCheckout({ ...checkout, deliveryAddress: e.target.value })} placeholder="Rua, número, bairro e complemento" /></div>}<div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Data e horário *</Label><Input type="datetime-local" value={checkout.scheduledAt} onChange={(e) => setCheckout({ ...checkout, scheduledAt: e.target.value })} /></div><div className="space-y-2"><Label>Forma de pagamento</Label><select value={checkout.paymentMethod} onChange={(e) => setCheckout({ ...checkout, paymentMethod: e.target.value as typeof checkout.paymentMethod })} className="h-10 w-full rounded-md border border-[#eaded8] bg-white px-3 text-sm"><option value="pix">PIX</option><option value="card">Cartão</option><option value="cash">Dinheiro</option></select></div></div><div className="space-y-2"><Label>Observações</Label><Textarea value={checkout.notes} onChange={(e) => setCheckout({ ...checkout, notes: e.target.value })} placeholder="Algum detalhe importante para a sua encomenda?" /></div></div><div className="h-fit rounded-3xl bg-[#633f39] p-6 text-white"><p className="text-xs uppercase tracking-wider text-[#f4cfc3]">Resumo</p><div className="mt-5 space-y-3">{cart.map((item) => <div key={item.productId} className="flex justify-between gap-3 text-sm text-[#f8e7e1]"><span>{item.quantity}× {item.productName}</span><span>{money(Number(item.unitPrice) * item.quantity)}</span></div>)}</div><div className="my-5 border-t border-white/20" /><div className="flex justify-between text-sm"><span>Entrega</span><span>{checkout.fulfillment === "delivery" ? money(8) : "Grátis"}</span></div><div className="mt-3 flex justify-between text-lg font-bold"><span>Total</span><span>{money(total)}</span></div><button disabled={createOrder.isPending} className="mt-6 w-full rounded-xl bg-[#f3c5b5] py-3.5 text-sm font-bold text-[#633f39] hover:bg-[#f7d6ca]">{createOrder.isPending ? "Enviando..." : "Confirmar pedido"}</button></div></form></div></div>}
    {showTracking && <div className="fixed inset-0 z-[70] grid place-items-center bg-[#3b2522]/30 p-5 backdrop-blur-sm"><div className="w-full max-w-lg rounded-3xl bg-[#fffaf7] p-7 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[#b9796b]">Acompanhamento</p><h2 className="mt-1 font-serif text-3xl text-[#4d2e2a]">Pedido #{trackingId}</h2></div><button onClick={() => setShowTracking(false)} className="rounded-full p-2 hover:bg-[#f9e9e2]"><X size={19} /></button></div>{trackingOrder.isLoading ? <p className="py-10 text-center text-sm text-[#987d77]">Consultando status...</p> : trackingOrder.data ? <div className="mt-7 space-y-3">{(["received", "in_production", "ready", "out_for_delivery", "delivered"] as const).map((status, index) => { const currentIndex = ["received", "in_production", "ready", "out_for_delivery", "delivered"].indexOf(trackingOrder.data!.status); return <div key={status} className={`flex items-center gap-3 rounded-2xl p-3 ${index <= currentIndex ? "bg-[#f9e9e2] text-[#633f39]" : "text-[#b9a39d]"}`}><span className={`grid h-8 w-8 place-items-center rounded-full text-xs font-bold ${index <= currentIndex ? "bg-[#e8a28f] text-white" : "bg-[#f1e6e1]"}`}>{index + 1}</span><span className="text-sm font-bold">{statusLabels[status]}</span>{index === currentIndex && <Badge className="ml-auto bg-[#633f39] text-white">Atual</Badge>}</div>; })}</div> : <p className="py-10 text-center text-sm text-[#987d77]">Pedido não encontrado.</p>}<p className="mt-6 text-center text-xs text-[#987d77]">O status é atualizado automaticamente a cada 15 segundos.</p></div></div>}
  </div>;
}

function AdminView(props: { section: "overview" | "orders" | "catalog" | "stock" | "production" | "finance"; setSection: (section: "overview" | "orders" | "catalog" | "stock" | "production" | "finance") => void; summary?: { revenue: number; orders: number; pending: number; production: number; averageTicket: number; lowStock: number }; paymentSummary?: { paid: number; pending: number; refunded: number }; productionAgenda: Array<{ task: { id: number; orderId: number; scheduledAt: Date; priority: "normal" | "high"; notes: string | null }; order: { customerName: string; status: keyof typeof statusLabels } }>; orders: Array<{ id: number; customerName: string; fulfillment: "pickup" | "delivery"; scheduledAt: Date; status: keyof typeof statusLabels; total: string; paymentMethod: keyof typeof paymentLabels; payment: { status: "pending" | "paid" | "refunded" } | null }>; ingredients: Array<{ id: number; name: string; unit: string; currentQuantity: string; minimumQuantity: string }>; lowStock: Array<{ id: number; name: string; unit: string; currentQuantity: string; minimumQuantity: string }>; isAuthenticated: boolean; isAdmin: boolean; onRequestLogin: () => void; userName: string; products: Array<{ product: { id: number; name: string; description: string; price: string | number; imageUrl: string | null; categoryId: number | null }; category: { name: string } | null }>; categories: Array<{ id: number; name: string }>; categoryName: string; setCategoryName: (name: string) => void; onCreateCategory: (event: React.FormEvent) => void; onDeleteCategory: (id: number) => void; productDraft: ProductDraft; setProductDraft: (draft: ProductDraft) => void; editingProductId: number | null; productEdit: (product: { id: number; name: string; description: string; price: string | number; imageUrl: string | null; categoryId: number | null }) => void; productDelete: (id: number) => void; ingredientDraft: IngredientDraft; setIngredientDraft: (draft: IngredientDraft) => void; onCreateProduct: (event: React.FormEvent) => void; onCreateIngredient: (event: React.FormEvent) => void; onUpdateStatus: (id: number, status: keyof typeof statusLabels) => void; onUpdatePayment: (orderId: number, status: "pending" | "paid" | "refunded") => void }) {
  const nav = [{ key: "overview", label: "Visão geral", icon: BarChart3 }, { key: "orders", label: "Pedidos", icon: ClipboardList }, { key: "production", label: "Produção", icon: CalendarDays }, { key: "catalog", label: "Catálogo", icon: CakeSlice }, { key: "stock", label: "Estoque", icon: Warehouse }, { key: "finance", label: "Financeiro", icon: CircleDollarSign }] as const;
  if (!props.isAuthenticated) return <main className="mx-auto max-w-4xl px-5 py-20 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-3xl bg-[#f9e9e2] text-[#b96758]"><LogIn size={28} /></div><h1 className="mt-5 font-serif text-4xl text-[#4d2e2a]">Área da confeitaria</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-[#987d77]">Entre com sua conta para acessar pedidos, catálogo, produção e estoque.</p><button onClick={props.onRequestLogin} className="mt-7 rounded-xl bg-[#633f39] px-5 py-3 text-sm font-bold text-white">Entrar no painel</button></main>;
  if (!props.isAdmin) return <main className="mx-auto max-w-4xl px-5 py-20 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-3xl bg-[#f9e9e2] text-[#b96758]"><ShieldAlert size={28} /></div><h1 className="mt-5 font-serif text-4xl text-[#4d2e2a]">Acesso restrito</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-[#987d77]">Sua conta ({props.userName}) não tem permissão de administrador. Peça para a gestora da confeitaria liberar seu acesso.</p></main>;
  return <main className="mx-auto max-w-7xl px-5 py-8 lg:px-8"><div className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.22em] text-[#b9796b]">Painel Miette</p><h1 className="mt-2 font-serif text-5xl text-[#4d2e2a]">Olá, {props.userName || "gestora"}.</h1><p className="mt-2 text-sm text-[#987d77]">Aqui está o pulso da sua confeitaria hoje.</p></div><div className="flex gap-2 rounded-2xl border border-[#f0e3dd] bg-white p-1">{nav.map(({ key, label, icon: Icon }) => <button key={key} onClick={() => props.setSection(key)} className={`flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold ${props.section === key ? "bg-[#633f39] text-white" : "text-[#987d77] hover:bg-[#faeee9]"}`}><Icon size={15} /> <span className="hidden sm:inline">{label}</span></button>)}</div></div>{props.section === "overview" && <><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric icon={CircleDollarSign} label="Faturamento" value={money(props.summary?.revenue ?? 0)} tint="peach" /><Metric icon={ShoppingBag} label="Pedidos" value={String(props.summary?.orders ?? 0)} tint="cream" /><Metric icon={Clock3} label="Pendentes" value={String(props.summary?.pending ?? 0)} tint="blue" /><Metric icon={TrendingUp} label="Ticket médio" value={money(props.summary?.averageTicket ?? 0)} tint="rose" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><div className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><div className="flex items-center justify-between"><div><h2 className="font-serif text-2xl text-[#4d2e2a]">Próximos pedidos</h2><p className="mt-1 text-xs text-[#987d77]">Acompanhe a produção do dia</p></div><button onClick={() => props.setSection("orders")} className="text-xs font-bold text-[#ae594c]">Ver todos</button></div><div className="mt-5">{props.orders.length === 0 ? <Empty text="Nenhum pedido recebido ainda." /> : props.orders.slice(0, 5).map((order) => <OrderRow key={order.id} order={order} onUpdateStatus={props.onUpdateStatus} onUpdatePayment={props.onUpdatePayment} />)}</div></div><div className="rounded-3xl bg-[#633f39] p-6 text-white"><p className="text-xs font-bold uppercase tracking-wider text-[#f4cfc3]">Atenção</p><h2 className="mt-2 font-serif text-3xl">Estoque baixo</h2><p className="mt-2 text-sm leading-6 text-[#f4e1db]">Ingredientes que precisam de reposição para manter a produção.</p><div className="mt-6 space-y-3">{props.lowStock.length === 0 ? <p className="rounded-xl bg-white/10 p-4 text-sm text-[#f4e1db]">Tudo certo por aqui.</p> : props.lowStock.slice(0, 4).map((item) => <div key={item.id} className="flex justify-between rounded-xl bg-white/10 px-4 py-3 text-sm"><span>{item.name}</span><strong>{item.currentQuantity}{item.unit}</strong></div>)}</div><button onClick={() => props.setSection("stock")} className="mt-5 flex items-center gap-2 text-xs font-bold text-[#f3c5b5]">Abrir estoque <ChevronRight size={15} /></button></div></div></>}{props.section === "orders" && <section className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Pedidos recebidos" subtitle="Organize cada encomenda até a entrega." icon={ClipboardList} /><div className="mt-5 space-y-2">{props.orders.length === 0 ? <Empty text="Ainda não há pedidos para exibir." /> : props.orders.map((order) => <OrderRow key={order.id} order={order} onUpdateStatus={props.onUpdateStatus} onUpdatePayment={props.onUpdatePayment} />)}</div></section>}{props.section === "catalog" && <section className="grid gap-6 lg:grid-cols-[1fr_1.1fr]"><div className="space-y-6"><div className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Categorias" subtitle="Organize o catálogo em grupos." icon={Filter} /><form onSubmit={props.onCreateCategory} className="mt-5 flex gap-2"><Input value={props.categoryName} onChange={(e) => props.setCategoryName(e.target.value)} placeholder="Ex.: Bolos, Tortas, Doces finos" /><Button type="submit" className="shrink-0 rounded-xl bg-[#633f39] text-white hover:bg-[#7a4f47]"><Plus size={16} /></Button></form>{props.categories.length > 0 && <div className="mt-4 flex flex-wrap gap-2">{props.categories.map((category) => <span key={category.id} className="flex items-center gap-2 rounded-full bg-[#f9e9e2] px-3 py-1.5 text-xs font-bold text-[#876b64]">{category.name}<button type="button" aria-label={`Remover categoria ${category.name}`} onClick={() => props.onDeleteCategory(category.id)} className="text-[#ae594c] hover:text-[#7a3f34]"><X size={12} /></button></span>)}</div>}</div><div className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Novo produto" subtitle="Publique um doce no catálogo." icon={CakeSlice} /><form onSubmit={props.onCreateProduct} className="mt-6 space-y-4"><div className="space-y-2"><Label>Nome do produto</Label><Input value={props.productDraft.name} onChange={(e) => props.setProductDraft({ ...props.productDraft, name: e.target.value })} placeholder="Ex.: Bolo de chocolate" /></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={props.productDraft.description} onChange={(e) => props.setProductDraft({ ...props.productDraft, description: e.target.value })} placeholder="Conte o que torna este doce especial" /></div><div className="space-y-2"><Label>Categoria</Label><select value={props.productDraft.categoryId} onChange={(e) => props.setProductDraft({ ...props.productDraft, categoryId: e.target.value })} className="h-10 w-full rounded-md border border-[#eaded8] bg-white px-3 text-sm"><option value="">Sem categoria</option>{props.categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Preço</Label><Input value={props.productDraft.price} onChange={(e) => props.setProductDraft({ ...props.productDraft, price: e.target.value })} placeholder="89.90" /></div><div className="space-y-2"><Label>URL da foto</Label><Input value={props.productDraft.imageUrl} onChange={(e) => props.setProductDraft({ ...props.productDraft, imageUrl: e.target.value })} placeholder="https://..." /><p className="text-[11px] text-[#987d77]">Cole a URL pública da imagem do produto.</p>{props.productDraft.imageUrl && <img src={props.productDraft.imageUrl} alt="Prévia do produto" className="h-24 w-24 rounded-xl object-cover" />}</div></div><Button className="w-full rounded-xl bg-[#633f39] text-white hover:bg-[#7a4f47]"><Plus size={16} /> Cadastrar produto</Button></form></div></div><div className="rounded-3xl bg-[#f9e9e2] p-6"><SectionTitle title="Catálogo publicado" subtitle={`${props.products.length} produtos ativos na loja.`} icon={ShoppingBag} /><div className="mt-5 space-y-2">{props.products.length === 0 ? <Empty text="Nenhum produto cadastrado." /> : props.products.map(({ product, category }) => <div key={product.id} className="flex items-center justify-between gap-3 rounded-2xl bg-white/70 p-3"><div><p className="text-sm font-bold text-[#4d2e2a]">{product.name}</p><p className="text-xs text-[#987d77]">{category?.name ?? "Sem categoria"} · {money(product.price)}</p></div><div className="flex gap-1"><button type="button" onClick={() => props.productEdit(product)} className="rounded-lg px-2 py-1 text-xs font-bold text-[#87574e] hover:bg-white">Editar</button><button type="button" onClick={() => props.productDelete(product.id)} className="rounded-lg px-2 py-1 text-xs font-bold text-[#ae594c] hover:bg-white">Excluir</button></div></div>)}</div></div></section>}{props.section === "production" && <section className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Agenda de produção" subtitle="Pedidos organizados por data e prioridade." icon={CalendarDays} /><div className="mt-5 space-y-2">{props.productionAgenda.length === 0 ? <Empty text="Nenhuma tarefa de produção agendada." /> : props.productionAgenda.map(({ task, order }) => <div key={task.id} className="flex flex-col gap-2 rounded-2xl border border-[#f0e3dd] p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold">Pedido #{task.orderId} · {order.customerName}</p><p className="mt-1 text-xs text-[#987d77]">{new Date(task.scheduledAt).toLocaleString("pt-BR")} · {statusLabels[order.status]}</p></div><Badge className={task.priority === "high" ? "bg-[#f5d4cf] text-[#985047]" : "bg-[#fff3d8] text-[#a0783c]"}>{task.priority === "high" ? "Prioridade alta" : "Prioridade normal"}</Badge></div>)}</div></section>}{props.section === "finance" && <section className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Controle financeiro" subtitle="Acompanhe pagamentos por status." icon={CircleDollarSign} /><div className="mt-6 grid gap-4 sm:grid-cols-3"><Metric icon={CircleDollarSign} label="Recebido" value={money(props.paymentSummary?.paid ?? 0)} tint="peach" /><Metric icon={Clock3} label="Pendente" value={money(props.paymentSummary?.pending ?? 0)} tint="cream" /><Metric icon={TrendingUp} label="Estornado" value={money(props.paymentSummary?.refunded ?? 0)} tint="rose" /></div><div className="mt-6 rounded-2xl bg-[#f9e9e2] p-5 text-sm leading-6 text-[#806761]">Os pagamentos são registrados junto ao pedido e podem começar com confirmação manual de PIX, cartão ou dinheiro. A integração automática pode ser adicionada sem alterar o fluxo.</div></section>}{props.section === "stock" && <section className="grid gap-6 lg:grid-cols-[1fr_1.1fr]"><div className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Novo ingrediente" subtitle="Controle os insumos da produção." icon={Warehouse} /><form onSubmit={props.onCreateIngredient} className="mt-6 space-y-4"><div className="space-y-2"><Label>Ingrediente</Label><Input value={props.ingredientDraft.name} onChange={(e) => props.setIngredientDraft({ ...props.ingredientDraft, name: e.target.value })} placeholder="Chocolate meio amargo" /></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Unidade</Label><Input value={props.ingredientDraft.unit} onChange={(e) => props.setIngredientDraft({ ...props.ingredientDraft, unit: e.target.value })} placeholder="g, kg, un" /></div><div className="space-y-2"><Label>Quantidade atual</Label><Input value={props.ingredientDraft.currentQuantity} onChange={(e) => props.setIngredientDraft({ ...props.ingredientDraft, currentQuantity: e.target.value })} /></div><div className="space-y-2"><Label>Estoque mínimo</Label><Input value={props.ingredientDraft.minimumQuantity} onChange={(e) => props.setIngredientDraft({ ...props.ingredientDraft, minimumQuantity: e.target.value })} /></div><div className="space-y-2"><Label>Custo por unidade</Label><Input value={props.ingredientDraft.costPerUnit} onChange={(e) => props.setIngredientDraft({ ...props.ingredientDraft, costPerUnit: e.target.value })} /></div></div><Button className="w-full rounded-xl bg-[#633f39] text-white hover:bg-[#7a4f47]"><Plus size={16} /> Cadastrar ingrediente</Button></form></div><div className="rounded-3xl border border-[#f0e3dd] bg-white p-6"><SectionTitle title="Inventário atual" subtitle={`${props.ingredients.length} ingredientes cadastrados.`} icon={Package} /><div className="mt-5 space-y-2">{props.ingredients.length === 0 ? <Empty text="Nenhum ingrediente cadastrado." /> : props.ingredients.map((item) => <div key={item.id} className="flex items-center justify-between rounded-2xl bg-[#fffaf7] px-4 py-3"><div><p className="text-sm font-bold">{item.name}</p><p className="text-xs text-[#987d77]">Mínimo: {item.minimumQuantity}{item.unit}</p></div><Badge className={Number(item.currentQuantity) <= Number(item.minimumQuantity) ? "bg-[#f5d4cf] text-[#985047]" : "bg-[#e4f0e7] text-[#4a7759]"}>{item.currentQuantity}{item.unit}</Badge></div>)}</div></div></section>}</main>;
}

function Metric({ icon: Icon, label, value, tint }: { icon: typeof CircleDollarSign; label: string; value: string; tint: string }) { const colors: Record<string, string> = { peach: "bg-[#f9e9e2] text-[#ae594c]", cream: "bg-[#fff3d8] text-[#a0783c]", blue: "bg-[#e5eff0] text-[#52777c]", rose: "bg-[#f4e2e5] text-[#a3626b]" }; return <div className="rounded-3xl border border-[#f0e3dd] bg-white p-5"><div className={`mb-5 grid h-10 w-10 place-items-center rounded-xl ${colors[tint]}`}><Icon size={19} /></div><p className="text-xs font-bold uppercase tracking-wider text-[#a58b84]">{label}</p><p className="mt-1 text-2xl font-bold text-[#4d2e2a]">{value}</p></div>; }
function SectionTitle({ title, subtitle, icon: Icon }: { title: string; subtitle: string; icon: typeof ClipboardList }) { return <div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f9e9e2] text-[#ae594c]"><Icon size={19} /></div><div><h2 className="font-serif text-2xl text-[#4d2e2a]">{title}</h2><p className="mt-1 text-xs text-[#987d77]">{subtitle}</p></div></div>; }
function Empty({ text }: { text: string }) { return <div className="rounded-2xl bg-[#fffaf7] p-8 text-center text-sm text-[#987d77]"><ClipboardList className="mx-auto mb-3 text-[#d9b4a9]" size={24} />{text}</div>; }
function OrderRow({ order, onUpdateStatus, onUpdatePayment }: { order: { id: number; customerName: string; fulfillment: "pickup" | "delivery"; scheduledAt: Date; status: keyof typeof statusLabels; total: string; paymentMethod: keyof typeof paymentLabels; payment: { status: "pending" | "paid" | "refunded" } | null }; onUpdateStatus: (id: number, status: keyof typeof statusLabels) => void; onUpdatePayment: (orderId: number, status: "pending" | "paid" | "refunded") => void }) {
  const next: Record<string, keyof typeof statusLabels> = { received: "in_production", in_production: "ready", ready: order.fulfillment === "delivery" ? "out_for_delivery" : "delivered", out_for_delivery: "delivered" };
  const paymentStatus = order.payment?.status ?? "pending";
  return <div className="flex flex-col gap-3 rounded-2xl border border-[#f0e3dd] bg-white p-4">
    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f9e9e2] text-[#ae594c]"><ClipboardList size={17} /></div><div><p className="text-sm font-bold">Pedido #{order.id} · {order.customerName}</p><p className="mt-1 text-xs text-[#987d77]">{new Date(order.scheduledAt).toLocaleString("pt-BR")} · {order.fulfillment === "delivery" ? "Entrega" : "Retirada"}</p></div></div>
      <div className="flex flex-wrap items-center gap-2"><Badge className="bg-[#e5eff0] text-[#52777c]">{statusLabels[order.status]}</Badge><strong className="text-sm text-[#ae594c]">{money(order.total)}</strong>{next[order.status] && <button onClick={() => onUpdateStatus(order.id, next[order.status])} className="rounded-lg bg-[#633f39] px-3 py-2 text-[11px] font-bold text-white">Avançar</button>}</div>
    </div>
    <div className="flex flex-wrap items-center gap-2 border-t border-[#f3e7e2] pt-3"><span className="text-xs font-bold text-[#806761]">Pagamento: {paymentStatus === "paid" ? "Pago" : paymentStatus === "refunded" ? "Estornado" : "Pendente"}</span><button onClick={() => onUpdatePayment(order.id, "paid")} className="rounded-lg bg-[#e4f0e7] px-3 py-1.5 text-[11px] font-bold text-[#4a7759]">Marcar pago</button><button onClick={() => onUpdatePayment(order.id, "pending")} className="rounded-lg bg-[#fff3d8] px-3 py-1.5 text-[11px] font-bold text-[#a0783c]">Pendente</button><button onClick={() => onUpdatePayment(order.id, "refunded")} className="rounded-lg bg-[#f5d4cf] px-3 py-1.5 text-[11px] font-bold text-[#985047]">Estornar</button></div>
  </div>;
}
